import{radiationFigure}from './rad1-figures.js?v=20261023-physicscomplete01';
const entries=[
['atoms','Electron energy transitions',['Absorb radiation: electron moves to higher level.','The nucleus stays unchanged.','Emit radiation: electron moves to lower level.','The emitted radiation carries energy away.']],
['evidence','A selected close alpha encounter',['Approach the foil.','Positive alpha approaches a positive nucleus.','Strong repulsion turns this selected trajectory.','Rare large deflections support a concentrated nucleus.']],
['radiation','Emission meets a barrier',['An unstable nucleus emits.','Radiation travels toward the barrier.','The illustrated alpha approaches paper.','Short-range alpha is stopped in this qualitative model.']],
['equations','Single alpha decay ledger',['Start with parent A210 Z84.','A helium nucleus separates.','The daughter loses four nucleons and two protons.','Daughter A206 Z82 plus alpha balances both accounts.']],
['half-life','Expected radioactive population',['Begin with eighty original nuclei.','After one half-life forty are expected.','After two half-lives twenty are expected.','After three half-lives ten are expected.']],
['hazards','Exposure and contamination',['An external source irradiates the surface.','Dust on the surface is itself radioactive material.','Its emissions continue locally.','Removing an external source does not remove deposited dust.']],
['background','A detector counts all contributions',['Background radiation reaches the detector.','Source radiation can also be detected.','Recorded events accumulate over the interval.','Subtract background to estimate the source contribution.']],
['uses','External detection of a gamma tracer',['A tracer emits from inside the body.','Gamma radiation can travel through tissue.','Some radiation escapes the body.','An external detector can record a signal.']],
['fission','A neutron can start a chain',['A neutron is absorbed.','The nucleus splits into smaller products.','Released neutrons travel outward.','Some neutrons can trigger another fission.']],
['fusion','Two light nuclei join',['Two light nuclei approach.','A selected energetic encounter brings them close.','A heavier nucleus and a neutron form in this example.','Products and radiation carry energy away.']]];
export const rad1Films=Object.fromEntries(entries.map(([k,title,steps])=>['rad1-'+k,{title,steps,duration:16,render:p=>radiationFigure({kind:k,movie:true,progress:p,...(k==='uses'?{a:'tracer',b:'gamma'}:{})}),note:'Original schematic; sizes, times, paths and event frequencies are exaggerated. Replay resets a worked example, not a real reversal of nuclear decay. Electron transitions differ from nuclear changes. Expected decay curves describe large populations; no individual decay schedule is predicted. Barriers give qualitative outcomes, not dose calculations or clinical advice. This model does not establish practical competence.'}]));
